import studio
from studio import api, Response, HTTPError

requests_t = studio.db.table('supply_requests')
approvers_t = studio.db.table('approvers')
notes_t = studio.db.table('notifications')
audit_t = studio.db.table('audit_log')

STATUSES = ['pending', 'approved', 'rejected']
PAGE = 25
EXPORT_MAX = 5000
EXPORT_COLS = ['id', 'item', 'quantity', 'reason', 'status', 'requester_name', 'requester_id', 'created_at', 'decided_by', 'decided_at', 'decision_note']
DECISIONS = {'approve': 'approved', 'approved': 'approved', 'reject': 'rejected', 'rejected': 'rejected'}


def fail(status, code, message, field=None):
    '''Raise a uniform error body.'''
    body = {'error': code, 'message': message}
    if field:
        body['field'] = field
    raise HTTPError(status, body)


def who(req):
    '''Return the verified caller id or refuse with 401.'''
    caller = req.caller or {}
    cid = caller.get('id')
    if not cid:
        fail(401, 'unauthenticated', 'Sign-in required')
    return str(cid)


def is_approver(cid):
    '''True when the id has an active row in approvers.'''
    return approvers_t.count({'user_id': cid, 'active': True}) > 0


def need_approver(req):
    '''Return the caller id, refusing with 403 unless an active approver.'''
    cid = who(req)
    if not is_approver(cid):
        fail(403, 'not_approver', 'Only approvers can do this')
    return cid


def audit(event, entity_id, actor, detail):
    '''Append an audit row.'''
    audit_t.insert({'event': event, 'entity': 'supply_requests', 'entity_id': str(entity_id), 'actor': actor, 'detail': detail})


def parse_id(raw):
    '''Parse a path id; anything malformed is a 404.'''
    try:
        n = int(raw)
    except (TypeError, ValueError):
        fail(404, 'not_found', 'Not found')
    if n < 1:
        fail(404, 'not_found', 'Not found')
    return n


def paging(req):
    '''Read limit and offset from the query (default 25, max 100).'''
    q = req.query or {}
    try:
        limit = int(q.get('limit') or PAGE)
        offset = int(q.get('offset') or 0)
    except ValueError:
        fail(422, 'validation_failed', 'limit and offset must be integers', 'limit')
    if limit < 1 or limit > 100 or offset < 0:
        fail(422, 'validation_failed', 'limit must be 1..100 and offset 0 or more', 'limit')
    return limit, offset


def status_filter(req):
    '''Read the optional status filter or refuse an unknown one.'''
    s = (req.query or {}).get('status')
    if s in (None, ''):
        return None
    if s not in STATUSES:
        fail(422, 'validation_failed', 'status must be pending, approved or rejected', 'status')
    return s


def shape(row, cid):
    '''Public view of a request row.'''
    return {
        'id': row['id'],
        'item': row['item'],
        'quantity': row['quantity'],
        'reason': row['reason'],
        'status': row['status'],
        'requester_name': row.get('requester_name'),
        'is_own': row.get('requester_id') == cid,
        'decided_by': row.get('decided_by'),
        'decided_at': row.get('decided_at'),
        'decision_note': row.get('decision_note'),
        'created_at': row['created_at'],
    }


def csv_cell(v):
    '''Quote one CSV cell and neutralise spreadsheet formulas.'''
    s = '' if v is None else str(v)
    if s[:1] in ('=', '+', '-', '@'):
        s = chr(39) + s
    return chr(34) + s.replace(chr(34), chr(34) + chr(34)) + chr(34)


def to_csv(rows, columns):
    '''CSV text with a header row.'''
    lines = [','.join(csv_cell(c) for c in columns)]
    for r in rows:
        lines.append(','.join(csv_cell(r.get(c)) for c in columns))
    return chr(10).join(lines) + chr(10)


def text_field(body, name, label, max_len):
    '''Validate a required, trimmed string field.'''
    v = body.get(name)
    if not isinstance(v, str) or not v.strip():
        fail(422, 'validation_failed', label + ' is required', name)
    v = v.strip()
    if len(v) > max_len:
        fail(422, 'validation_failed', label + ' must be at most ' + str(max_len) + ' characters', name)
    return v


@api.post('/requests', auth='app_token', name='createRequest', description='Submit a supply request (starts pending)')
def create_request(req):
    '''Create a request. Returns {id, item, quantity, reason, status, requester_name, is_own, decided_by, decided_at, decision_note, created_at}'''
    cid = who(req)
    body = req.json()
    if not isinstance(body, dict):
        fail(422, 'validation_failed', 'A JSON object is required')
    item = text_field(body, 'item', 'Item', 200)
    reason = text_field(body, 'reason', 'Reason', 1000)
    qty = body.get('quantity')
    if isinstance(qty, str) and qty.strip().isdigit():
        qty = int(qty.strip())
    if isinstance(qty, bool) or not isinstance(qty, int) or qty < 1 or qty > 1000:
        fail(422, 'validation_failed', 'Quantity must be a whole number from 1 to 1000', 'quantity')
    caller = req.caller or {}
    row = requests_t.insert({
        'item': item,
        'quantity': qty,
        'reason': reason,
        'status': 'pending',
        'requester_id': cid,
        'requester_name': caller.get('name') or cid,
        'created_by': cid,
    })
    audit('submitted', row['id'], cid, str(qty) + ' x ' + item)
    return Response(201, shape(row, cid))


@api.get('/requests/mine', auth='app_token', name='listMyRequests', description='The caller own requests, newest first')
def list_mine(req):
    '''List the caller own requests. Returns {rows: [{id, item, quantity, reason, status, decided_by, decided_at, decision_note, created_at}], total, limit, offset}'''
    cid = who(req)
    limit, offset = paging(req)
    flt = {'requester_id': cid}
    s = status_filter(req)
    if s:
        flt['status'] = s
    page = requests_t.page(flt, sort='-created_at', limit=limit, offset=offset)
    return {'rows': [shape(r, cid) for r in page['rows']], 'total': page['total'], 'limit': limit, 'offset': offset}


@api.get('/requests/summary', auth='app_token', name='requestSummary', description='Request count per status (approvers only)')
def summary(req):
    '''Count requests per status. Returns {pending, approved, rejected, total}'''
    need_approver(req)
    out = {}
    for s in STATUSES:
        out[s] = requests_t.count({'status': s})
    out['total'] = out['pending'] + out['approved'] + out['rejected']
    return out


@api.get('/requests/export', auth='app_token', name='exportRequests', description='CSV export of requests, max 5000 rows (approvers only)')
def export_requests(req):
    '''Export requests as CSV. Returns {filename, content_type, csv}'''
    need_approver(req)
    s = status_filter(req)
    flt = {'status': s} if s else {}
    rows = []
    offset = 0
    while len(rows) < EXPORT_MAX:
        page = requests_t.page(flt, sort='-created_at', limit=1000, offset=offset)
        rows.extend(page['rows'])
        offset += 1000
        if offset >= page['total']:
            break
    rows = rows[:EXPORT_MAX]
    return {
        'filename': 'supply-requests-' + (s or 'all') + '.csv',
        'content_type': 'text/csv',
        'csv': to_csv(rows, EXPORT_COLS),
    }


@api.get('/requests', auth='app_token', name='listRequests', description='All requests for approvers, optional status filter')
def list_requests(req):
    '''List all requests (approvers only). Returns {rows: [{id, item, quantity, reason, status, requester_name, is_own, decided_by, decided_at, decision_note, created_at}], total, limit, offset}'''
    cid = need_approver(req)
    limit, offset = paging(req)
    s = status_filter(req)
    flt = {'status': s} if s else {}
    page = requests_t.page(flt, sort='-created_at', limit=limit, offset=offset)
    return {'rows': [shape(r, cid) for r in page['rows']], 'total': page['total'], 'limit': limit, 'offset': offset}


@api.get('/requests/{id}', auth='app_token', name='getRequest', description='One request; requester or approver only')
def get_request(req):
    '''Get one request. Returns {id, item, quantity, reason, status, requester_name, is_own, decided_by, decided_at, decision_note, created_at}'''
    cid = who(req)
    rid = parse_id(req.params['id'])
    row = requests_t.get(rid)
    if row is None:
        fail(404, 'not_found', 'Request not found')
    if row['requester_id'] != cid and not is_approver(cid):
        fail(403, 'forbidden', 'You cannot view this request')
    return shape(row, cid)


@api.post('/requests/{id}/decision', auth='app_token', name='decideRequest', description='Approve or reject a pending request')
def decide(req):
    '''Decide a request. Returns {id, status, decided_by, decided_at, decision_note}'''
    rid = parse_id(req.params['id'])
    body = req.json()
    if not isinstance(body, dict):
        body = {}
    raw = body.get('decision')
    target = DECISIONS.get(raw) if isinstance(raw, str) else None
    if target is None:
        fail(422, 'invalid_decision', 'decision must be approved or rejected', 'decision')
    note = body.get('note')
    if note is None:
        note = ''
    if not isinstance(note, str):
        fail(422, 'validation_failed', 'note must be text', 'note')
    note = note.strip()
    if len(note) > 1000:
        fail(422, 'validation_failed', 'note must be at most 1000 characters', 'note')
    cid = need_approver(req)
    row = requests_t.get(rid)
    if row is None:
        fail(404, 'not_found', 'Request not found')
    if row['requester_id'] == cid:
        fail(403, 'own_request', 'You cannot decide your own request')
    if row['status'] != 'pending':
        if row['status'] == target:
            return decision_out(row)
        fail(409, 'already_decided', 'This request was already ' + row['status'])
    if target == 'rejected' and not note:
        fail(422, 'note_required', 'A note is required when rejecting', 'note')
    changes = {'status': target, 'decided_by': cid, 'updated_by': cid}
    if note:
        changes['decision_note'] = note
    updated = requests_t.update(rid, changes)
    updated = requests_t.update(rid, {'decided_at': updated['updated_at']})
    message = 'Your request for ' + str(row['quantity']) + ' x ' + row['item'] + ' was ' + target + '.'
    if note:
        message = message + ' ' + note
    notes_t.insert({
        'recipient_id': row['requester_id'],
        'request_id': rid,
        'kind': 'request_approved' if target == 'approved' else 'request_rejected',
        'message': message,
        'read': False,
    })
    audit(target, rid, cid, note)
    return decision_out(updated)


def decision_out(row):
    '''Decision fields of a request row.'''
    return {
        'id': row['id'],
        'status': row['status'],
        'decided_by': row.get('decided_by'),
        'decided_at': row.get('decided_at'),
        'decision_note': row.get('decision_note'),
    }


@api.get('/approvers/me', auth='app_token', name='getMyApproverStatus', description='Whether the caller is an active approver')
def approver_me(req):
    '''Report approver status. Returns {is_approver}'''
    cid = who(req)
    return {'is_approver': is_approver(cid)}


@api.get('/notifications', auth='app_token', name='listNotifications', description='The caller inbox, newest first, optional unread filter')
def list_notifications(req):
    '''List the caller inbox. Returns {rows: [{id, request_id, kind, message, read, created_at}], total, unread, limit, offset}'''
    cid = who(req)
    limit, offset = paging(req)
    flt = {'recipient_id': cid}
    unread = (req.query or {}).get('unread')
    if unread in ('true', '1'):
        flt['read'] = False
    elif unread not in (None, '', 'false', '0'):
        fail(422, 'validation_failed', 'unread must be true or false', 'unread')
    page = notes_t.page(flt, sort='-created_at', limit=limit, offset=offset)
    rows = [{
        'id': n['id'],
        'request_id': n['request_id'],
        'kind': n['kind'],
        'message': n['message'],
        'read': n['read'],
        'created_at': n['created_at'],
    } for n in page['rows']]
    return {'rows': rows, 'total': page['total'], 'unread': notes_t.count({'recipient_id': cid, 'read': False}), 'limit': limit, 'offset': offset}


@api.post('/notifications/{id}/read', auth='app_token', name='markNotificationRead', description='Mark one of the caller notifications read')
def mark_read(req):
    '''Mark a notification read. Returns {id, read}'''
    cid = who(req)
    nid = parse_id(req.params['id'])
    n = notes_t.get(nid)
    if n is None:
        fail(404, 'not_found', 'Notification not found')
    if n['recipient_id'] != cid:
        fail(403, 'forbidden', 'This notification is not yours')
    if not n['read']:
        n = notes_t.update(nid, {'read': True})
    return {'id': n['id'], 'read': True}

