/**
 * Office Supplies app entry. Resolves whether the caller is an approver, then
 * mounts the AppShell with staff screens and, for managers, Review and Dashboard.
 */
import { useEffect, useState } from 'react';
import { AppShell, Button, EmptyState, Spinner, errorInfo } from './kit';
import { api } from './api/client';
import NewRequest from './views/NewRequest';
import MyRequests from './views/MyRequests';
import Inbox from './views/Inbox';
import Review from './views/Review';
import Dashboard from './views/Dashboard';

/** Root component of the Office Supplies app. */
export default function App() {
  const [approver, setApprover] = useState<boolean | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let live = true;
    setError(null);
    api
      .getMyApproverStatus()
      .then((r: any) => {
        if (live) setApprover(!!r.is_approver);
      })
      .catch((e: unknown) => {
        if (live) setError(errorInfo(e).message);
      });
    return () => {
      live = false;
    };
  }, [attempt]);

  if (error) {
    return (
      <div className='h-full flex items-center justify-center p-4'>
        <EmptyState
          title='Could not load the app'
          hint={error}
          action={<Button onClick={() => setAttempt(attempt + 1)}>Retry</Button>}
        />
      </div>
    );
  }
  if (approver === null) {
    return (
      <div className='h-full flex items-center justify-center'>
        <Spinner size={24} />
      </div>
    );
  }

  const screens: any[] = [
    { id: 'new', label: 'New request', render: (go: (id: string) => void) => <NewRequest onDone={() => go('mine')} /> },
    { id: 'mine', label: 'My requests', render: () => <MyRequests /> },
    { id: 'inbox', label: 'Inbox', render: () => <Inbox /> },
  ];
  if (approver) {
    screens.push({ id: 'review', label: 'Review', render: () => <Review /> });
    screens.push({ id: 'dashboard', label: 'Dashboard', render: () => <Dashboard /> });
  }
  return <AppShell title='Office Supplies' screens={screens} />;
}

/**
 * Resource definitions that bind the kit's data blocks (tables, forms) to the
 * generated typed client. Two views of the same rows: the caller's own and all.
 */
import { api } from './api/client';
import type { ResourceDef } from './kit';

const fields: ResourceDef['fields'] = [
  { name: 'item', label: 'Item', type: 'string', required: true },
  { name: 'quantity', label: 'Quantity', type: 'integer', required: true, help: 'Between 1 and 1000' },
  { name: 'reason', label: 'Reason', type: 'text', required: true },
  { name: 'status', label: 'Status', type: 'string', enum: ['pending', 'approved', 'rejected'], readOnly: true },
  { name: 'requester_name', label: 'Requested by', type: 'string', readOnly: true },
  { name: 'decision_note', label: 'Decision note', type: 'text', readOnly: true },
  { name: 'created_at', label: 'Submitted', type: 'datetime', readOnly: true },
  { name: 'decided_at', label: 'Decided', type: 'datetime', readOnly: true },
];

/** The signed-in user's own requests: list and create. */
export const myRequests: ResourceDef = {
  name: 'my_requests',
  label: 'My requests',
  singular: 'request',
  titleField: 'item',
  fields,
  client: {
    list: (q: any) => api.listMyRequests(q),
    get: (id: any) => api.getRequest({ id }),
    create: (body: any) => api.createRequest(body),
  },
};

/** Every request, for approvers (read-only list; decisions go through the decision route). */
export const allRequests: ResourceDef = {
  name: 'all_requests',
  label: 'All requests',
  singular: 'request',
  titleField: 'item',
  fields,
  client: {
    list: (q: any) => api.listRequests(q),
    get: (id: any) => api.getRequest({ id }),
  },
};

/**
 * New request screen: a form for item, quantity and reason. Server validation
 * errors appear on the matching field.
 */
import { Card, Page, ResourceForm, notify } from '../kit';
import { myRequests } from '../resources';

/** Form screen for submitting a supply request; calls onDone after a successful save. */
export default function NewRequest({ onDone }: { onDone: () => void }) {
  return (
    <Page title='New request' subtitle='Ask for office supplies. A manager will review it.'>
      <div className='max-w-xl'>
        <Card title='Request details'>
          <ResourceForm
            resource={myRequests}
            fields={['item', 'quantity', 'reason']}
            initial={{ quantity: 1 }}
            submitLabel='Submit request'
            onSaved={() => {
              notify('Request submitted', 'ok');
              onDone();
            }}
          />
        </Card>
      </div>
    </Page>
  );
}

/**
 * My requests screen: the caller's own requests with status and decision note,
 * filterable by status.
 */
import { useState } from 'react';
import { Page, ResourceTable, Tabs } from '../kit';
import { myRequests } from '../resources';

const TABS = [
  { id: 'all', label: 'All' },
  { id: 'pending', label: 'Pending' },
  { id: 'approved', label: 'Approved' },
  { id: 'rejected', label: 'Rejected' },
];

/** Status-tabbed table of the signed-in user's requests (25 per page). */
export default function MyRequests() {
  const [tab, setTab] = useState('all');
  const filters = tab === 'all' ? {} : { status: tab };
  return (
    <Page title='My requests' subtitle='Everything you have asked for and what was decided.'>
      <div className='mb-3'>
        <Tabs tabs={TABS} value={tab} onChange={setTab} />
      </div>
      <ResourceTable
        resource={myRequests}
        columns={['item', 'quantity', 'status', 'decision_note', 'created_at']}
        filters={filters}
        pageSize={25}
        emptyText='No requests here yet.'
      />
    </Page>
  );
}

/**
 * Inbox screen: decision notifications for the caller, unread first by default,
 * with a mark-as-read action. Refreshes every 30 seconds.
 */
import { useCallback, useEffect, useState } from 'react';
import { Button, Card, EmptyState, Page, Spinner, Tabs, Tag, errorInfo, notify, timeAgo } from '../kit';
import { api } from '../api/client';

const PAGE = 25;
const TABS = [
  { id: 'unread', label: 'Unread' },
  { id: 'all', label: 'All' },
];

/** List of the caller's notifications with per-item mark-as-read and load-more paging. */
export default function Inbox() {
  const [tab, setTab] = useState('unread');
  const [rows, setRows] = useState<any[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<number | null>(null);

  const load = useCallback(
    async (offset: number) => {
      setLoading(true);
      try {
        const q: any = { limit: String(PAGE), offset: String(offset) };
        if (tab === 'unread') q.unread = 'true';
        const r: any = await api.listNotifications(q);
        setRows((prev) => (offset === 0 ? r.rows : [...prev, ...r.rows]));
        setTotal(r.total);
        setError(null);
      } catch (e) {
        setError(errorInfo(e).message);
      } finally {
        setLoading(false);
      }
    },
    [tab],
  );

  useEffect(() => {
    load(0);
    const t = setInterval(() => load(0), 30000);
    return () => clearInterval(t);
  }, [load]);

  const markRead = async (id: number) => {
    setBusyId(id);
    try {
      await api.markNotificationRead({ id });
      await load(0);
    } catch (e) {
      notify(errorInfo(e).message, 'error');
    } finally {
      setBusyId(null);
    }
  };

  return (
    <Page title='Inbox' subtitle='Decisions on your requests.'>
      <div className='mb-3'>
        <Tabs tabs={TABS} value={tab} onChange={setTab} />
      </div>
      {error && (
        <EmptyState title='Could not load your inbox' hint={error} action={<Button onClick={() => load(0)}>Retry</Button>} />
      )}
      {!error && loading && rows.length === 0 && (
        <div className='flex justify-center p-8'>
          <Spinner size={24} />
        </div>
      )}
      {!error && !loading && rows.length === 0 && (
        <EmptyState title={tab === 'unread' ? 'Nothing unread' : 'No notifications yet'} hint='You are told here when a manager decides one of your requests.' />
      )}
      <div className='flex flex-col gap-2'>
        {rows.map((n) => (
          <Card key={n.id}>
            <div className='flex items-start justify-between gap-3'>
              <div className='min-w-0'>
                <div className='flex items-center gap-2 mb-1'>
                  <Tag tone={n.kind === 'request_approved' ? 'green' : 'red'}>
                    {n.kind === 'request_approved' ? 'Approved' : 'Rejected'}
                  </Tag>
                  {!n.read && <Tag tone='blue'>New</Tag>}
                  <span className='text-xs text-gray-500'>{timeAgo(n.created_at)}</span>
                </div>
                <p className='text-sm break-words'>{n.message}</p>
              </div>
              {!n.read && (
                <Button size='sm' variant='secondary' loading={busyId === n.id} onClick={() => markRead(n.id)}>
                  Mark read
                </Button>
              )}
            </div>
          </Card>
        ))}
      </div>
      {rows.length < total && (
        <div className='flex justify-center mt-3'>
          <Button variant='ghost' loading={loading} onClick={() => load(rows.length)}>
            Load more
          </Button>
        </div>
      )}
    </Page>
  );
}

/**
 * Review screen for managers: every request filtered by status (pending first),
 * with a drawer to approve or reject. Rejecting requires a note.
 */
import { useState } from 'react';
import { Button, Drawer, Page, ResourceTable, StatusBadge, Tabs, errorInfo, notify } from '../kit';
import { api } from '../api/client';
import { allRequests } from '../resources';

const TABS = [
  { id: 'pending', label: 'Pending' },
  { id: 'approved', label: 'Approved' },
  { id: 'rejected', label: 'Rejected' },
  { id: 'all', label: 'All' },
];

/** Approver queue with a decision drawer; calls the decision route and refreshes the table. */
export default function Review() {
  const [tab, setTab] = useState('pending');
  const [sel, setSel] = useState<any>(null);
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [reload, setReload] = useState(0);
  const filters = tab === 'all' ? {} : { status: tab };

  const close = () => {
    setSel(null);
    setNote('');
    setErr(null);
  };

  const decide = async (decision: 'approved' | 'rejected') => {
    if (!sel) return;
    if (decision === 'rejected' && !note.trim()) {
      setErr('A note is required when rejecting.');
      return;
    }
    setBusy(decision);
    setErr(null);
    try {
      await api.decideRequest({ id: sel.id }, { decision, note: note.trim() });
      notify('Request ' + decision, 'ok');
      close();
      setReload((r) => r + 1);
    } catch (e) {
      setErr(errorInfo(e).message);
    } finally {
      setBusy(null);
    }
  };

  const canDecide = sel && sel.status === 'pending' && !sel.is_own;

  return (
    <Page title='Review' subtitle='Approve or reject supply requests.'>
      <div className='mb-3'>
        <Tabs tabs={TABS} value={tab} onChange={setTab} />
      </div>
      <ResourceTable
        resource={allRequests}
        columns={['item', 'quantity', 'requester_name', 'status', 'created_at']}
        filters={filters}
        pageSize={25}
        reloadKey={reload}
        onSelect={(row: any) => {
          setSel(row);
          setNote('');
          setErr(null);
        }}
        selectedId={sel ? sel.id : undefined}
        emptyText='No requests in this view.'
      />
      <Drawer
        open={!!sel}
        onClose={close}
        title={sel ? sel.item : ''}
        subtitle={sel ? 'Requested by ' + (sel.requester_name || 'unknown') : ''}
        footer={
          canDecide ? (
            <div className='flex gap-2 justify-end'>
              <Button variant='danger' loading={busy === 'rejected'} disabled={busy !== null} onClick={() => decide('rejected')}>
                Reject
              </Button>
              <Button variant='success' loading={busy === 'approved'} disabled={busy !== null} onClick={() => decide('approved')}>
                Approve
              </Button>
            </div>
          ) : undefined
        }
      >
        {sel && (
          <div className='flex flex-col gap-3 text-sm'>
            <div className='flex items-center gap-2'>
              <StatusBadge status={sel.status} />
              <span>Quantity: {sel.quantity}</span>
            </div>
            <div>
              <div className='text-xs text-gray-500'>Reason</div>
              <p className='break-words'>{sel.reason}</p>
            </div>
            {sel.decision_note && (
              <div>
                <div className='text-xs text-gray-500'>Decision note</div>
                <p className='break-words'>{sel.decision_note}</p>
              </div>
            )}
            {sel.is_own && <p className='text-amber-600'>This is your own request; another manager must decide it.</p>}
            {canDecide && (
              <label className='flex flex-col gap-1'>
                <span className='text-xs text-gray-500'>Note (required to reject)</span>
                <textarea
                  className='border rounded p-2 min-h-[80px]'
                  maxLength={1000}
                  value={note}
                  onChange={(e) => setNote(e.target.value)}
                />
              </label>
            )}
            {err && <p className='text-red-600'>{err}</p>}
          </div>
        )}
      </Drawer>
    </Page>
  );
}

/**
 * Dashboard screen for managers: request counts per status from the summary
 * route (refreshed every 30 seconds) and a CSV export.
 */
import { useCallback, useEffect, useState } from 'react';
import { Button, Card, EmptyState, Page, Spinner, Stat, errorInfo, notify } from '../kit';
import { api } from '../api/client';

const STATUSES: { key: string; label: string; tone: 'amber' | 'green' | 'red' }[] = [
  { key: 'pending', label: 'Pending', tone: 'amber' },
  { key: 'approved', label: 'Approved', tone: 'green' },
  { key: 'rejected', label: 'Rejected', tone: 'red' },
];
const BAR: Record<string, string> = { pending: 'bg-amber-400', approved: 'bg-green-500', rejected: 'bg-red-500' };

/** Status counts with proportional bars plus a CSV export filtered by status. */
export default function Dashboard() {
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [exportStatus, setExportStatus] = useState('');
  const [exporting, setExporting] = useState(false);

  const load = useCallback(async () => {
    try {
      setData(await api.requestSummary());
      setError(null);
    } catch (e) {
      setError(errorInfo(e).message);
    }
  }, []);

  useEffect(() => {
    load();
    const t = setInterval(load, 30000);
    return () => clearInterval(t);
  }, [load]);

  const doExport = async () => {
    setExporting(true);
    try {
      const r: any = exportStatus ? await api.exportRequests({ status: exportStatus }) : await api.exportRequests();
      const blob = new Blob([r.csv], { type: 'text/csv;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = r.filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      notify('Export ready', 'ok');
    } catch (e) {
      notify(errorInfo(e).message, 'error');
    } finally {
      setExporting(false);
    }
  };

  return (
    <Page
      title='Dashboard'
      subtitle='Requests by status.'
      actions={
        <div className='flex items-center gap-2'>
          <select
            className='border rounded px-2 py-1 text-sm'
            value={exportStatus}
            onChange={(e) => setExportStatus(e.target.value)}
          >
            <option value=''>All statuses</option>
            <option value='pending'>Pending</option>
            <option value='approved'>Approved</option>
            <option value='rejected'>Rejected</option>
          </select>
          <Button variant='secondary' loading={exporting} onClick={doExport}>
            Export CSV
          </Button>
        </div>
      }
    >
      {error && <EmptyState title='Could not load the summary' hint={error} action={<Button onClick={load}>Retry</Button>} />}
      {!error && !data && (
        <div className='flex justify-center p-8'>
          <Spinner size={24} />
        </div>
      )}
      {!error && data && (
        <div className='flex flex-col gap-4'>
          <div className='grid grid-cols-2 md:grid-cols-4 gap-3'>
            {STATUSES.map((s) => (
              <Stat key={s.key} label={s.label} value={data[s.key]} tone={s.tone} />
            ))}
            <Stat label='Total' value={data.total} tone='blue' />
          </div>
          <Card title='Share of requests'>
            <div className='flex flex-col gap-3'>
              {STATUSES.map((s) => {
                const pct = data.total ? Math.round((data[s.key] / data.total) * 100) : 0;
                return (
                  <div key={s.key}>
                    <div className='flex justify-between text-sm mb-1'>
                      <span>{s.label}</span>
                      <span>{data[s.key]} ({pct}%)</span>
                    </div>
                    <div className='h-2 rounded bg-gray-100 overflow-hidden'>
                      <div className={'h-full ' + BAR[s.key]} style={{ width: pct + '%' }} />
                    </div>
                  </div>
                );
              })}
            </div>
          </Card>
        </div>
      )}
    </Page>
  );
}
